# name: participant_side_bias_sd
# description: Between-participant standard deviation of each person's left-choice rate; observed above null_mean means individuals have stable personal left/right response biases that the model (no side term) under-produces.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().std())

# name: left_choice_rate
# description: Overall proportion of trials on which the LEFT sequence was chosen; observed above the model's null_mean means people have a left-side response bias the model (which has no side term) under-produces, below means a right bias.
def test_statistic(df):
    return float(df["chose_left"].mean())

# name: periodic_pattern_choice
# description: Among pairs where exactly one sequence repeats a block of period 3 or 4 (e.g. HHTHHT, HTTTHTTT; not strict alternation), the proportion choosing the periodic one; observed below null_mean means people see repeating patterns as non-random more than the model (no periodicity term) predicts.
def test_statistic(df):
    def periodic(s):
        n = len(s)
        if n < 6:
            return False
        if all(s[i] == s[i + 2] for i in range(n - 2)):
            return False
        for p in (3, 4):
            if n >= 2 * p - 1 and all(s[i] == s[i + p] for i in range(n - p)):
                return True
        return False
    a = df["sequence_a"]; b = df["sequence_b"]
    m = {s: periodic(s) for s in pd.unique(pd.concat([a, b]))}
    pa = a.map(m).to_numpy(bool); pb = b.map(m).to_numpy(bool)
    sel = pa != pb
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose_per = np.where(pa, c, 1 - c)
    return float(chose_per[sel].mean())

# name: short_seq_more_alternating_choice
# description: Among pairs of length <= 5 whose alternation rates differ, the proportion choosing the sequence with more alternations; observed far from null_mean means the model's length-normalised features mis-scale how strongly alternation drives choices for short sequences (above: people favour alternation more than predicted).
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
    a = df["sequence_a"]; b = df["sequence_b"]
    m = {s: alt(s) for s in pd.unique(pd.concat([a, b]))}
    aa = a.map(m).to_numpy(); bb = b.map(m).to_numpy()
    L = a.str.len().to_numpy()
    sel = (L <= 5) & (aa != bb)
    if sel.sum() == 0:
        return 0.5
    chose_more = np.where(aa > bb, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    return float(chose_more[sel].mean())

# name: shorter_initial_run_choice
# description: Among pairs whose opening runs (streak at the start) differ in length but whose longest runs are equal, the proportion choosing the sequence with the shorter opening run; observed above null_mean means people penalise starting streaks more than the model (which only weights the final run) predicts.
def test_statistic(df):
    def first_run(s):
        n = 1
        while n < len(s) and s[n] == s[0]:
            n += 1
        return n
    def longest(s):
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return best
    a = df["sequence_a"]; b = df["sequence_b"]
    u = pd.unique(pd.concat([a, b]))
    fr = {s: first_run(s) for s in u}; lr = {s: longest(s) for s in u}
    fa = a.map(fr).to_numpy(); fb = b.map(fr).to_numpy()
    la = a.map(lr).to_numpy(); lb = b.map(lr).to_numpy()
    sel = (fa != fb) & (la == lb)
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose_shorter = np.where(fa < fb, c, 1 - c)
    return float(chose_shorter[sel].mean())

# name: more_heads_choice
# description: Among pairs whose head counts differ, the proportion choosing the sequence with MORE heads; the model is symmetric under swapping H and T, so observed far from null_mean means a heads/tails asymmetry (above: heads-heavy sequences look more random than predicted).
def test_statistic(df):
    ha = df["sequence_a"].str.count("H").to_numpy(); hb = df["sequence_b"].str.count("H").to_numpy()
    sel = ha != hb
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    return float(np.where(ha > hb, c, 1 - c)[sel].mean())
